local card={api_version=1,id="LOOT_079",name="Wandering Monster",text="<b>Secret:</b> When an enemy attacks your hero, summon a 3-Cost minion as the new target.",set="LOOTAPALOOZA",type="spell",class="hunter",rarity="rare",cost=2,keywords={"secret"}}
card.triggers={{event="attack",timing="before",active_zones={"secret"},condition=function(ctx,self,event)local p=ctx:controller(self);return event.attacker~=ctx:player(p).hero and event.defender==ctx:player(p).hero and #ctx:board(p)<7 end,effect=function(ctx,self,event)local pool={};for _,id in ipairs(ctx:collectible_cards())do local d=ctx:card_definition(id);if d.type=="minion"and d.cost==3 then pool[#pool+1]=id end end;if #pool==0 then return end;ctx:reveal_secret(self);ctx:set_data(self,"wandering_attack",event.event_id);for _,e in ipairs(ctx:board(ctx:controller(self)))do ctx:set_data(self,"wandering_seen:"..e,1)end;ctx:random_value(pool,"wandering_chosen")end}}
function card.wandering_chosen(ctx,self,id)ctx:summon(ctx:controller(self),id);ctx:continue_with("wandering_redirect")end
function card.wandering_redirect(ctx,self)for _,e in ipairs(ctx:board(ctx:controller(self)))do if ctx:get_data(self,"wandering_seen:"..e)==0 then ctx:set_attack_defender(ctx:get_data(self,"wandering_attack"),e);return end end end
return card
